using System.Linq;using UnityEngine;using UnityEditor;using IndianOceanAssets.ShooterSurvival;
public static class InspectArchivedCrown { public static object Main(){ var d=Object.FindFirstObjectByType<Chapter45Director>();var a=d.transform.Find("Preserved_PreDetailed_58F_118F_20261003");return new{anchors=a.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="CrownShell"||t.name=="WhiteShoeOffering").Select(t=>new{t.name,position=t.position.ToString("F3"),meshes=t.GetComponentsInChildren<Renderer>(true).Select(r=>new{r.name,min=r.bounds.min.ToString("F3"),max=r.bounds.max.ToString("F3")}).ToArray()}).ToArray(),goals=a.GetComponentsInChildren<Chapter45Goal>(true).Select(g=>new{g.name,g.floor,g.offering,position=g.transform.position.ToString("F3")}).ToArray()};} }
